{
  "schema": "duplex-runtime.qwen3-alignment.v1",
  "text": "我实际只是快走，不跑步，也不做间歇。这样周三可以吗？",
  "sample_rate": 16000,
  "frames": 79360,
  "audio_sha256": "3ca31ec591c8b04a8e0ac3e0e602c6c05900b167ff4440599d45bb6732a49f71",
  "source": "independent_posthoc_forced_alignment",
  "items": [
    {
      "text": "我",
      "start_time": 0.8,
      "end_time": 0.8
    },
    {
      "text": "实",
      "start_time": 0.8,
      "end_time": 0.96
    },
